/**
 * Generated by `createschema ai.AISkill 'name:Text; description:Text; content:Text; license?:Text; compatibility?:Text; metadata?:Json; allowedTools?:Text; image?:File; examples?:Json; b2bApp:Relationship:B2BApp:SET_NULL; scope:Select:global,organization,personal; organization?:Relationship:Organization:SET_NULL; user?:Relationship:User:SET_NULL;' --force`
 */

const { historical, versioned, uuided, tracked, softDeleted, dvAndSender, analytical } = require('@open-condo/keystone/plugins')
const { GQLListSchema } = require('@open-condo/keystone/schema')

const access = require('@condo/domains/ai/access/AISkill')
const { LOGO_FIELD } = require('@condo/domains/miniapp/schema/fields/integration')


const SKILL_NAME_REGEX = /^[a-z0-9]+(-[a-z0-9]+)*$/
const SKILL_NAME_MAX_LENGTH = 64
const SKILL_DESCRIPTION_MAX_LENGTH = 1024
const SKILL_COMPATIBILITY_MAX_LENGTH = 500

const AISkill = new GQLListSchema('AISkill', {
    schemaDoc: 'AI assistant skill in Agent Skills format. Can be provided by a B2BApp (miniapp) or created by users. Used by the AI assistant in the ai-engineer section',
    fields: {

        name: {
            schemaDoc: 'Skill name. Lowercase letters, numbers, and hyphens only. Max 64 characters.',
            type: 'Text',
            isRequired: true,
        },

        description: {
            schemaDoc: 'What the skill does and when to use it. Max 1024 characters. The AI uses this to decide when to trigger the skill.',
            type: 'Text',
            isRequired: true,
        },

        content: {
            schemaDoc: 'Markdown instructions body. The procedural content the AI follows when the skill runs.',
            type: 'Text',
            isRequired: true,
        },

        license: {
            schemaDoc: 'License name or reference to a bundled license file. Optional.',
            type: 'Text',
        },

        compatibility: {
            schemaDoc: 'Environment requirements. Max 500 characters. Optional.',
            type: 'Text',
        },

        metadata: {
            schemaDoc: 'Arbitrary key-value mapping for additional metadata. Optional.',
            type: 'Json',
        },

        allowedTools: {
            schemaDoc: 'Space-separated string of pre-approved tools the skill may use. Optional.',
            type: 'Text',
        },

        image: {
            ...LOGO_FIELD,
            schemaDoc: 'Skill illustration image. Shown on skill cards and detail view.',
        },

        examples: {
            schemaDoc: 'Array of example prompt strings shown as suggestion tags under chat input.',
            type: 'Json',
            graphQLInputType: '[String!]',
            graphQLReturnType: '[String!]',
        },

        b2bApp: {
            schemaDoc: 'B2BApp that provides this skill. If set, this skill originated from a miniapp.',
            type: 'Relationship',
            ref: 'B2BApp',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

        scope: {
            schemaDoc: 'Visibility scope. "global" = all users. "organization" = org employees. "personal" = creator only.',
            type: 'Select',
            options: 'global,organization,personal',
            isRequired: true,
            defaultValue: 'global',
        },

        organization: {
            schemaDoc: 'Organization for org-scoped skills. Required when scope=organization.',
            type: 'Relationship',
            ref: 'Organization',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

        user: {
            schemaDoc: 'User for personal skills. Required when scope=personal.',
            type: 'Relationship',
            ref: 'User',
            kmigratorOptions: { null: true, on_delete: 'models.SET_NULL' },
        },

    },
    hooks: {
        validateInput: ({ resolvedData, existingItem, addValidationError }) => {
            const newItem = { ...existingItem, ...resolvedData }

            const name = newItem.name
            if (name) {
                if (name.length > SKILL_NAME_MAX_LENGTH) {
                    addValidationError(`Skill name must be at most ${SKILL_NAME_MAX_LENGTH} characters`)
                }
                if (!SKILL_NAME_REGEX.test(name)) {
                    addValidationError('Skill name must contain only lowercase letters, numbers, and hyphens. Must not start or end with a hyphen.')
                }
            }

            const description = newItem.description
            if (description && description.length > SKILL_DESCRIPTION_MAX_LENGTH) {
                addValidationError(`Skill description must be at most ${SKILL_DESCRIPTION_MAX_LENGTH} characters`)
            }

            const content = newItem.content
            if (!content || !content.trim()) {
                addValidationError('Skill content must not be empty')
            }

            const compatibility = newItem.compatibility
            if (compatibility && compatibility.length > SKILL_COMPATIBILITY_MAX_LENGTH) {
                addValidationError(`Skill compatibility must be at most ${SKILL_COMPATIBILITY_MAX_LENGTH} characters`)
            }

            const examples = newItem.examples
            if (examples !== undefined && examples !== null) {
                if (!Array.isArray(examples) || !examples.every(e => typeof e === 'string')) {
                    addValidationError('Examples must be an array of strings')
                }
            }

            const scope = newItem.scope
            if (scope === 'organization' && !newItem.organization) {
                addValidationError('Organization must be set when scope is "organization"')
            }
            if (scope === 'personal' && !newItem.user) {
                addValidationError('User must be set when scope is "personal"')
            }
            if (scope === 'global' && (newItem.organization || newItem.user)) {
                addValidationError('Organization and user must not be set when scope is "global"')
            }

            if (newItem.b2bApp && scope !== 'global') {
                addValidationError('Skills linked to a B2BApp must have scope "global"')
            }
        },
    },
    plugins: [uuided(), versioned(), tracked(), softDeleted(), dvAndSender(), historical(), analytical()],
    access: {
        read: access.canReadAISkills,
        create: access.canManageAISkills,
        update: access.canManageAISkills,
        delete: false,
        auth: true,
    },
})

module.exports = {
    AISkill,
}
